CREATE TRIGGER RefShippingLine_Version_Create
	ON RefShippingLine
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT RSL_PK, 'RSL'
	FROM inserted
GO
CREATE TRIGGER RefShippingLine_Version_Update
	ON RefShippingLine
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON RSL_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
